import unittest
from tasktray import shortlist

class ShortlistTests(unittest.TestCase):
    def test_selection(self):
        items = [
            {'id': 'c', 'title': 'Cedar', 'done': False},
            {'id': 'a', 'title': 'Amber', 'done': False},
            {'id': 'b', 'title': 'Birch', 'done': False},
        ]
        self.assertEqual(shortlist(items, 2), ['a', 'b', 'c'])

    def test_done_is_excluded(self):
        items = [{'id': 'x', 'title': 'Elm', 'done': True}]
        self.assertEqual(shortlist(items, 2), [])
